      "أسس اختيار الصديق الصالح المتمثلة في حسن الأخلاق، رجاحة العقل، والتوافق الفكري والعمري.",
      "حقوق الصداقة الواجبة كالتناصح، وحسن المعاملة، والتماس الأعذار، والتواصل المستمر.",
      "صداقة الرسول ﷺ وأبي بكر الصديق رضي الله عنه كأعظم نموذج عملي للصداقة والوفاء.",
      "أهمية الاعتدال والتوازن في مشاعر الحب والبغض تجاه الأصدقاء لتجنب الندم."
